    private val job = Job()
    private val scope = CoroutineScope(Dispatchers.IO + job)

    suspend fun getUser(id: String): UserProfile {
        return scope.async { repo.findById(id) }.await()
    }

    fun shutdown() {
        job.cancel()
    }
}
```

